// The hub UDP messages (frontend/lib/udp_commands/commands/*), checked byte for byte against the
// frames backend/hubload/udp_protocol.py builds. hubloadFrames.json was generated by running
// hubload's encode() and scan_reply_payload() with the backend's Python (2026-11-23); the
// encrypted credential message is checked against OpenSSL here, since hubload's AES needs a
// package that venv does not have.

import { createCipheriv } from 'crypto';

import frames from './hubloadFrames.json';
import {
  AbstractUdpCommand,
  CheckandSaveEncryptedSSIDandPassword,
  CheckandSaveEncryptedSSIDandPasswordReply,
  CheckandSaveSSIDandPassword,
  getUdpCommand,
  GetFWVersion,
  GetFWVersionReply,
  QueryWifiTestResult,
  QueryWifiTestResultReply,
  ReadWebsocketUri,
  ReadWebsocketUriReply,
  ResetDevice,
  SaveSSIDandPassword,
  SaveSSIDandPasswordReply,
  SaveWebsocketUri,
  ScanWifiNetworks,
  ScanWifiNetworksReply,
  TestSSIDandPassword,
  udpCommands,
} from '../../src/udpCommands/commands';
import { baseUrlWs } from '../../src/config/environment';

const hex = (command: AbstractUdpCommand) =>
  Buffer.from(
    command.data.buffer,
    command.data.byteOffset,
    command.data.byteLength,
  ).toString('hex');

/** A received datagram: a DataView over exactly its bytes. */
const datagram = (hexString: string) => {
  const bytes = Uint8Array.from(Buffer.from(hexString, 'hex'));
  return new DataView(bytes.buffer);
};

const AES_KEY = Buffer.from('daf1327423c533ad0c258c1b279d3944', 'hex');
const AES_IV = Buffer.from('2264a2335473a3bcb2a2342112544299', 'hex');

function opensslField(value: string): Buffer {
  const padded = Buffer.alloc(64);
  Buffer.from(value, 'utf8').copy(padded);
  const cipher = createCipheriv('aes-128-cbc', AES_KEY, AES_IV);
  cipher.setAutoPadding(false);
  return Buffer.concat([cipher.update(padded), cipher.final()]);
}

describe('generate() builds the frame hubload builds', () => {
  test.each([
    ['getFwVersion', () => GetFWVersion.generate()],
    [
      'getFwVersionReply_1025',
      () => GetFWVersionReply.generate({ version: 1025 }),
    ],
    ['scanWifi', () => ScanWifiNetworks.generate()],
    ['reset', () => ResetDevice.generate()],
    ['queryTestResult', () => QueryWifiTestResult.generate()],
    ['readWsUri', () => ReadWebsocketUri.generate()],
    [
      'scanReply_short',
      () =>
        ScanWifiNetworksReply.generate({
          success: 1,
          resultNumber: 0,
          totalNumberOfResults: 1,
          bssid: [0, 0, 0, 0, 0, 0],
          ssid: 'surveillance_van4',
          primaryChannel: 6,
          secondaryChannel: 0,
          rssi: -57,
          otherWifiData: '',
        }),
    ],
    [
      'scanReply_full33',
      () =>
        ScanWifiNetworksReply.generate({
          success: 1,
          resultNumber: 2,
          totalNumberOfResults: 5,
          bssid: [],
          ssid: 'abcdefghijklmnopqrstuvwxyz0123456',
          primaryChannel: 11,
          secondaryChannel: 1,
          rssi: -81,
          otherWifiData: 'extra',
        }),
    ],
    [
      'scanReply_cafe',
      () =>
        ScanWifiNetworksReply.generate({
          success: 1,
          resultNumber: 1,
          totalNumberOfResults: 3,
          bssid: [],
          ssid: 'café ☕',
          primaryChannel: 1,
          secondaryChannel: 0,
          rssi: -60,
          otherWifiData: '',
        }),
    ],
    [
      'saveWsUri_dev',
      () => SaveWebsocketUri.generate({ uri: 'ws://192.168.100.29:8000/hub/' }),
    ],
    [
      'saveWsUri_long',
      () => SaveWebsocketUri.generate({ uri: frames._long_uri }),
    ],
    [
      'readWsUriReply_live',
      () => ReadWebsocketUriReply.generate({ uri: 'wss://cartellap.com/hub/' }),
    ],
    [
      'queryTestResultReply_2',
      () => QueryWifiTestResultReply.generate({ result: 2 }),
    ],
    [
      'saveCredentialsReply_1',
      () => SaveSSIDandPasswordReply.generate({ result: 1 }),
    ],
    [
      'checkAndSaveEncryptedReply_1',
      () => CheckandSaveEncryptedSSIDandPasswordReply.generate({ result: 1 }),
    ],
    [
      'saveCredentials',
      () =>
        SaveSSIDandPassword.generate({
          ssid: 'Home Wifi',
          password: 'MyWifiPass123',
        }),
    ],
    [
      'testCredentials',
      () =>
        TestSSIDandPassword.generate({ ssid: 'café', password: 'pässwörd' }),
    ],
    [
      'checkAndSave',
      () =>
        CheckandSaveSSIDandPassword.generate({
          ssid: 'Home Wifi',
          password: 'MyWifiPass123',
        }),
    ],
  ] as const)('%s', (name, build) => {
    expect(hex(build())).toBe(frames[name]);
  });

  test('the credential message is the two OpenSSL AES-128-CBC fields in a 144-byte frame', () => {
    const command = CheckandSaveEncryptedSSIDandPassword.generate({
      ssid: 'Home Wifi',
      password: 'MyWifiPass123',
    });
    const frame = Buffer.alloc(144);
    Buffer.from('deadbeef', 'hex').copy(frame, 0);
    frame.writeUInt32LE(0x000a0123, 4);
    frame.writeUInt32LE(144, 8);
    opensslField('Home Wifi').copy(frame, 12);
    opensslField('MyWifiPass123').copy(frame, 76);
    let sum = 0;
    for (let i = 0; i < 140; i++) sum += frame[i];
    frame.writeUInt32LE(sum, 140);

    expect(hex(command)).toBe(frame.toString('hex'));
  });

  test('the credential message refuses a value over 64 bytes, as encryptDataBytes does', () => {
    expect(() =>
      CheckandSaveEncryptedSSIDandPassword.generate({
        ssid: 'Home',
        password: 'é'.repeat(33),
      }),
    ).toThrow('value is 66 UTF-8 bytes');
  });

  test("Save Websocket Uri defaults to this build's server: <baseUrlWs>/hub/", () => {
    const command = SaveWebsocketUri.generate();
    expect(command.uri).toBe('wss://test.cartellap.com/hub/');
    expect(command.uri).toBe(`${baseUrlWs()}/hub/`);
    expect(SaveWebsocketUri.parse(command.data).uri).toBe(
      'wss://test.cartellap.com/hub/',
    );
  });

  test('a scan reply ignores the BSSID it is given, as Flutter does', () => {
    const command = ScanWifiNetworksReply.generate({
      success: 1,
      resultNumber: 0,
      totalNumberOfResults: 1,
      bssid: [1, 2, 3, 4, 5, 6],
      ssid: 'surveillance_van4',
      primaryChannel: 6,
      secondaryChannel: 0,
      rssi: -57,
      otherWifiData: '',
    });
    expect(hex(command)).toBe(frames.scanReply_short);
    // A view of everything from byte 24 to the end of the frame.
    expect(command.bssid).toHaveLength(84);
  });
});

describe('getUdpCommand (AbstractUdpCommand.get) reads what the hub sends', () => {
  test('routes each type the app knows to its parser', () => {
    expect([...udpCommands.keys()].sort()).toEqual(
      [
        '000A0001',
        '000B0002',
        '000A00C4',
        '000B00C5',
        '000A0003',
        '000A00C7',
        '000B00C8',
        '000A00C9',
        '000B00CA',
        '000A00C6',
        '000A0123',
        '000B0124',
        '000A00E2',
        '000A00E0',
        '000B00E1',
      ].sort(),
    );
  });

  test('a firmware version reply', () => {
    const reply = getUdpCommand(datagram(frames.getFwVersionReply_1025));
    expect(reply).toBeInstanceOf(GetFWVersionReply);
    expect((reply as GetFWVersionReply).version).toBe(1025);
    expect(reply.messageType).toBe('000B0002');
    expect(reply.messageLength).toBe(20);
    expect(reply.checksum).toBe(0x35e);
  });

  test('a scan reply: name without padding, signal, channels, and the BSSID view', () => {
    const reply = getUdpCommand(
      datagram(frames.scanReply_withBssid),
    ) as ScanWifiNetworksReply;
    expect(reply).toBeInstanceOf(ScanWifiNetworksReply);
    expect(reply.ssid).toBe('Home');
    expect(reply.rssi).toBe(-40);
    expect(reply.primaryChannel).toBe(6);
    expect(reply.success).toBe(1);
    expect(reply.totalNumberOfResults).toBe(1);
    expect(Array.from(reply.bssid).slice(0, 6)).toEqual([
      0x00, 0x11, 0x22, 0x33, 0x44, 0x55,
    ]);
    expect(reply.bssid).toHaveLength(84);

    const full = getUdpCommand(
      datagram(frames.scanReply_full33),
    ) as ScanWifiNetworksReply;
    expect(full.ssid).toBe('abcdefghijklmnopqrstuvwxyz0123456');
    expect(full.otherWifiData).toBe('extra');
    expect(full.secondaryChannel).toBe(1);
    expect(full.resultNumber).toBe(2);

    expect(
      (getUdpCommand(datagram(frames.scanReply_cafe)) as ScanWifiNetworksReply)
        .ssid,
    ).toBe('café ☕');
  });

  test('the three replies with a result field', () => {
    expect(
      (
        getUdpCommand(
          datagram(frames.checkAndSaveEncryptedReply_1),
        ) as CheckandSaveEncryptedSSIDandPasswordReply
      ).resultStatus(),
    ).toBe('Success!');
    expect(
      (
        getUdpCommand(
          datagram(frames.saveCredentialsReply_1),
        ) as SaveSSIDandPasswordReply
      ).result,
    ).toBe(1);
    expect(
      (
        getUdpCommand(
          datagram(frames.queryTestResultReply_2),
        ) as QueryWifiTestResultReply
      ).resultStatus(),
    ).toBe('Success!');
  });

  test('a websocket address reply, cut at 128 bytes when written', () => {
    expect(
      (
        getUdpCommand(
          datagram(frames.readWsUriReply_live),
        ) as ReadWebsocketUriReply
      ).uri,
    ).toBe('wss://cartellap.com/hub/');
    expect(
      (getUdpCommand(datagram(frames.saveWsUri_long)) as SaveWebsocketUri).uri,
    ).toBe(frames._long_uri.slice(0, 128));
  });

  test('a wrong checksum is not rejected: it reads as 0', () => {
    const bytes = Buffer.from(frames.getFwVersionReply_1025, 'hex');
    bytes[19] = 255 - bytes[19];
    const reply = getUdpCommand(
      new DataView(Uint8Array.from(bytes).buffer),
    ) as GetFWVersionReply;
    expect(reply).toBeInstanceOf(GetFWVersionReply);
    expect(reply.version).toBe(1025);
    expect(reply.checksum).toBe(0);
  });

  test('an unknown type, and the unrouted plaintext check-and-save, parse as plain messages', () => {
    const bytes = Buffer.from(frames.getFwVersion, 'hex');
    bytes.writeUInt32LE(0x000b9999, 4);
    const unknown = getUdpCommand(new DataView(Uint8Array.from(bytes).buffer));
    expect(unknown.constructor).toBe(AbstractUdpCommand);
    expect(unknown.messageType).toBe('000B9999');

    const unrouted = getUdpCommand(datagram(frames.checkAndSave));
    expect(unrouted.constructor).toBe(AbstractUdpCommand);
    expect(unrouted.messageType).toBe('000A0101');
  });

  test('a frame too short for its fields throws RangeError, as ByteData does', () => {
    expect(() => getUdpCommand(datagram('deadbeef'))).toThrow(RangeError);
    // Declares 20 bytes but carries 16.
    expect(() =>
      getUdpCommand(datagram('deadbeef02000b0014000000010400005e')),
    ).toThrow(RangeError);
  });

  test('the parser reads only its own view of a larger buffer', () => {
    const inner = Buffer.from(frames.scanReply_short, 'hex');
    const outer = new Uint8Array(inner.length + 50);
    outer.set(inner, 10);
    const reply = getUdpCommand(
      new DataView(outer.buffer, 10, inner.length),
    ) as ScanWifiNetworksReply;
    expect(reply.ssid).toBe('surveillance_van4');
    expect(reply.bssid).toHaveLength(84);
  });
});

describe('the log forms', () => {
  test('packetToHexString drops leading zeros, byte by byte', () => {
    expect(GetFWVersion.generate().packetToHexString()).toBe(
      '0xdeadbeef10a01000053300',
    );
  });

  test('toString lists the type, title, length, data, checksum and raw bytes', () => {
    const lines = GetFWVersionReply.generate({ version: 1025 })
      .toString()
      .split('\n');
    expect(lines[0]).toBe(
      '      Packet Type : 000B0002 : Get Firmware Version - Reply',
    );
    expect(lines[1]).toBe('      Description : ');
    expect(lines[2]).toBe('      Length : 20');
    expect(lines[3]).toMatch(
      /^ {6}Time : \d{4}-\d\d-\d\d \d\d:\d\d:\d\d\.\d{6}$/,
    );
    expect(lines.slice(4, 7)).toEqual([
      '      Data: {',
      '      Version : 1025',
      '      }',
    ]);
    expect(lines[7]).toBe('      Checksum : 862');
    expect(lines[8]).toBe(
      '      Raw data : DE AD BE EF 02 00 0B 00 14 00 00 00 01 04 00 00 5E 03 00 00 ',
    );
  });
});
